"""Paste this ENTIRE file into ONE A100 Colab cell. Google Drive authorization required before training.

Three-seed replay + fixed evaluation-pool transfer + actual checkpoint download.
Allow 50 GiB local runtime disk and at least 30 GB free in Google Drive for checkpoint copies + the ZIP.
"""
import base64
import hashlib
import json
from pathlib import Path
import runpy
import subprocess
import sys
import tempfile
import zlib

BASE_COMMIT = '7e7cfea90b60415dc9561efbe97bcd383cc1580e'
BUNDLE_SHA256 = '6220877888ce2d303f420ee118966bf3d552e88cff9adcb98162ea099a1679bc'
PAYLOAD = ''

def run_all():
    if not Path('/content').is_dir():
        raise RuntimeError('Run this cell in Google Colab with an A100 GPU.')
    payload = zlib.decompress(base64.b64decode(PAYLOAD))
    if hashlib.sha256(payload).hexdigest() != BUNDLE_SHA256:
        raise RuntimeError('Embedded source checksum mismatch')
    sources = json.loads(payload)
    from google.colab import drive
    drive.mount('/content/drive')
    staging = Path(tempfile.mkdtemp(prefix='otco_transfer_source_', dir='/content'))
    repo = staging/'repo'
    subprocess.run(['git','clone','--no-checkout','https://github.com/akashm776/otco.git',str(repo)], check=True)
    subprocess.run(['git','-C',str(repo),'checkout','--detach',BASE_COMMIT], check=True)
    if subprocess.check_output(['git','-C',str(repo),'rev-parse','HEAD'], text=True).strip() != BASE_COMMIT:
        raise RuntimeError('Wrong pinned checkout')
    for name, source in sources.items():
        relative = Path(name)
        if relative.is_absolute() or '..' in relative.parts:
            raise RuntimeError('Unsafe overlay path')
        path = repo/relative
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(source)
    print('Three seeds: 789, 2026, 31415; checkpoints: 100, 250, 500, 750, 1001.')
    print('Original-state replay checks + different CUB evaluation pool; frozen rules, no curriculum training.')
    print('Drive backups enabled: checkpoints copied as they close; full verified ZIP saved too.')
    print('Destination: MyDrive/OTCO/evaluation_transfer/<run_id> (roughly 25 GB total).')
    print('A100 required. Keep the runtime until DRIVE_SYNC_COMPLETE. No browser download required.')
    previous = sys.argv[:]
    try:
        script = repo/'colabs/run_clip_evaluation_transfer.py'
        sys.argv = [str(script), '--bundle-id', BUNDLE_SHA256] + ['--drive-root', '/content/drive/MyDrive/OTCO/evaluation_transfer']
        runpy.run_path(str(script), run_name='__main__')
    finally:
        sys.argv = previous

run_all()
